function redis_read($s){ $c=fread($s,1); if($c===false||$c==='')return null; if($c==='+'){return rtrim(fgets($s),"\r\n");} if($c==='-'){return 'ERR:'.rtrim(fgets($s),"\r\n");} if($c===':'){return intval(trim(fgets($s)));} if($c==='$'){ $l=fgets($s);$n=intval(trim($l));if($n===-1)return null;$d='';while(strlen($d)<$n){$b=fread($s,$n-strlen($d));if($b===false||$b==='')break;$d.=$b;}fread($s,2);return $d;} if($c==='*'){ $l=fgets($s);$n=intval(trim($l));if($n===-1)return null;$a=[];for($i=0;$i<$n;$i++)$a[]=redis_read($s);return $a;} return 'RAW:'.ord($c); }
function redis_cmd($s,$cmd){ $p=preg_split('/\s+/',trim($cmd));$o='*'.count($p)."\r\n";foreach($p as $x)$o.='$'.strlen($x)."\r\n".$x."\r\n";fwrite($s,$o);return redis_read($s); }
